#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Teach Clock on Google Play (batch 08, ticket 15).
#
# Walks the author through every step of docs/android-release.md that only a
# person can do, in timeline order: the Play developer account, the machine,
# the upload key and its four secrets, the repo variables, the Play Console
# forms, the first upload, the testers, the service account, the 14-day closed
# test, Apply for production, the production release and Teacher Approved.
#
#   bash scripts/release-wizard.sh             # the real run
#   bash scripts/release-wizard.sh --dry-run   # runs and writes nothing (see usage)
#
# Nothing changes without a "y": every gh secret/variable write, keytool,
# brew, Gradle, download and workflow run asks first and shows the command.
# Re-runnable: GitHub secrets and variables are checked live, dates live in
# docs/store/closed-test.md (labels only, the repo is public), and the other
# finished stages are remembered in .env.release (git-ignored). Secrets are
# never written to disk.
# ──────────────────────────────────────────────────────────────────────────

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
DRY_RUN=0
GUIDE="$ROOT/docs/android-release.md"
CLOSED_TEST="$ROOT/docs/store/closed-test.md"
WEBSITE_URL="https://denysslobodianyk1996.github.io/teach-clock/"
PRIVACY_URL="${WEBSITE_URL}privacy.html"
PACKAGE_ID=$(sed -n 's/^ *applicationId "\(.*\)"$/\1/p' "$ROOT/android/app/build.gradle")
KEY_ALIAS=upload
AAB=android/app/build/outputs/bundle/release/app-release.aab
PLAY_CONSOLE="https://play.google.com/console"
SDK_DIR="${ANDROID_HOME:-$HOME/Library/Android/sdk}"

# Values filled in along the way (globals, so set -u never trips on them).
JDK="" SECRET_NAMES="" VARS="" GH_OK=0 REPO=""
KEYSTORE_PATH="" KEY_PW="" SUPPORT_URL="" GROUP_URL="" OPTIN_URL=""
JSON_PATH="" CI_RUN="" CI_ARTIFACT="" NOTES_UK="" NOTES_EN=""

usage() {
  cat <<'EOF'
Usage: bash scripts/release-wizard.sh [--dry-run]

Walks you through publishing Teach Clock on Google Play (docs/android-release.md).

  -n, --dry-run   show every step and command, run none of them: no gh writes,
                  no keytool, no build, no browser; dates go to a temp copy of
                  docs/store/closed-test.md and progress to a temp state file
  -h, --help      this text
EOF
}

parse_args() {
  local arg
  for arg in "$@"; do
    case "$arg" in
      -n|--dry-run) DRY_RUN=1 ;;
      -h|--help) usage; exit 0 ;;
      *) printf 'Unknown option: %s\n\n' "$arg" >&2; usage >&2; exit 2 ;;
    esac
  done
}

# ── Helpers ───────────────────────────────────────────────────────────────

# show_cmd ARGS... prints a command as the author would type it.
show_cmd() {
  local out="" a
  for a in "$@"; do
    if [[ -z "$a" || "$a" =~ [[:space:]\'\"\$\<\>\|\;\&\(\)] ]]; then out+=" \"$a\""; else out+=" $a"; fi
  done
  printf '    %s$%s%s\n' "$DIM" "$out" "$RESET"
}

# offer "question" CMD...: shows CMD and runs it only after a yes (never in a dry run).
# Returns 1 when the author says no, or the command's own status.
offer() {
  local question="$1"; shift
  show_cmd "$@"
  if ! confirm "$question"; then note "Not run. You can run it yourself later."; return 1; fi
  if (( DRY_RUN )); then note "(dry run: not run)"; return 0; fi
  "$@"
}

show_raw() { printf '    %s$ %s%s\n' "$DIM" "$1" "$RESET"; }

open_link() {
  if (( DRY_RUN )); then printf '  %s↗ would open%s %s\n' "$GREEN" "$RESET" "$1"; else open_url "$1"; fi
}

put_secret() {
  if (( DRY_RUN )); then note "(dry run) would set GitHub secret $1"; return 0; fi
  set_secret "$1" "$2"
}

put_var() {
  if (( DRY_RUN )); then note "(dry run) would set GitHub variable $1=$2"; return 0; fi
  set_var "$1" "$2"
}

# refresh_gh reads which secrets and variables the repo already has (read-only).
refresh_gh() {
  GH_OK=0 SECRET_NAMES="" VARS="" REPO=""
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    GH_OK=1
    REPO=$(gh repo view --json nameWithOwner --jq .nameWithOwner 2>/dev/null || true)
    SECRET_NAMES=$(gh secret list --json name --jq '.[].name' 2>/dev/null || true)
    VARS=$(gh variable list --json name,value --jq '.[] | "\(.name)=\(.value)"' 2>/dev/null || true)
  fi
}
has_secret() { grep -qx "$1" <<<"$SECRET_NAMES"; }
var_value() { sed -n "s/^$1=//p" <<<"$VARS" | head -n1; }

# A finished stage that leaves no other trace is remembered as KEY=yes in .env.release.
is_done() { [[ "$(_existing "$1" || true)" == yes ]]; }
mark_done() { write_env "$1" yes; }

# date_of "Label": the date in that Key dates row of docs/store/closed-test.md, or nothing.
date_of() {
  awk -F'|' -v label="$1" '
    { a = $2; gsub(/^ +| +$/, "", a); b = $3; gsub(/^ +| +$/, "", b) }
    NF == 4 && a == label { print b; exit }' "$CLOSED_TEST"
}

# set_date "Label" YYYY-MM-DD fills that row's date cell (the cell is sized for a date).
set_date() {
  local tmp; tmp=$(mktemp)
  awk -F'|' -v OFS='|' -v label="$1" -v d="$2" '
    { a = $2; gsub(/^ +| +$/, "", a) }
    NF == 4 && a == label { $3 = " " d " " }
    { print }' "$CLOSED_TEST" > "$tmp"
  cat "$tmp" > "$CLOSED_TEST"
  rm -f "$tmp"
  printf '  %s✓ wrote%s %s: %s → %s\n' "$GREEN" "$RESET" "$1" "$2" "${CLOSED_TEST#"$ROOT"/}"
}

# ask_date VAR "question": a YYYY-MM-DD date, Enter for today; gives up after three bad tries.
ask_date() {
  local var="$1" prompt="$2" answer="" tries=0 today
  today=$(date +%F)
  while (( tries < 3 )); do
    printf '  %s%s%s %s[Enter = %s]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$today" "$RESET"
    read -r answer || answer=""
    answer=${answer:-$today}
    if [[ "$answer" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]]; then printf -v "$var" '%s' "$answer"; return 0; fi
    warn "Use the form YYYY-MM-DD, for example $today."
    tries=$((tries + 1))
  done
  return 1
}

# record "Label" "question" asks for a date and writes it to closed-test.md.
record() {
  local when=""
  if ask_date when "$2"; then set_date "$1" "$when"; fi
}

add_days() {
  date -j -v+"$2"d -f %F "$1" +%F 2>/dev/null || date -d "$1 + $2 days" +%F
}

# ask_https VAR "prompt": an https:// link (Enter keeps the remembered one); three tries.
ask_https() {
  local tries=0
  while (( tries < 3 )); do
    ask "$1" "$2" || return 1
    if [[ "${!1}" =~ ^https://[^[:space:]]+$ ]]; then return 0; fi
    warn "That isn't an https:// link."
    tries=$((tries + 1))
  done
  return 1
}

# already KEY ["date label"]: true when the stage was finished on an earlier run
# and the author doesn't want to go through it again.
already() {
  local when=""
  if [[ -n "${2:-}" ]]; then when=$(date_of "$2"); fi
  if is_done "$1" || [[ -n "$when" ]]; then
    say "${GREEN}✓ Done${RESET}${when:+ on $when}."
    if confirm "Go through this stage again?"; then return 1; fi
    return 0
  fi
  return 1
}

# not_yet "what": this stage has to wait for an earlier one.
not_yet() {
  say "${YELLOW}Not yet.${RESET} This stage comes after $1."
  say "Run the wizard again then; it skips what is already done."
  pause
}

find_jdk() {
  local p
  for p in "${JAVA_HOME:-}" "$(brew --prefix openjdk@21 2>/dev/null || true)" \
    /opt/homebrew/opt/openjdk@21 /usr/local/opt/openjdk@21; do
    [[ -n "$p" && -x "$p/bin/java" ]] || continue
    if "$p/bin/java" -version 2>&1 | grep -q 'version "21'; then JDK="$p"; return 0; fi
  done
  return 1
}

keytool_bin() {
  if find_jdk; then printf '%s' "$JDK/bin/keytool"; return 0; fi
  command -v keytool 2>/dev/null
}

# check_password FILE PASSWORD: 0 right, 1 wrong, 2 no keytool to check with. Read-only.
check_password() {
  local kt
  kt=$(keytool_bin) || return 2
  if STOREPASS="$2" "$kt" -list -keystore "$1" -alias "$KEY_ALIAS" -storepass:env STOREPASS >/dev/null 2>&1; then
    return 0
  fi
  return 1
}

# ask_key_password reads the keystore password into KEY_PW (hidden) and checks it.
ask_key_password() {
  local tries=0 rc
  while (( tries < 3 )); do
    ask_secret KEY_PW "Keystore password (hidden):" || return 1
    if check_password "$KEYSTORE_PATH" "$KEY_PW"; then return 0; else rc=$?; fi
    if (( rc == 2 )); then warn "No keytool found, so the password can't be checked."; return 0; fi
    warn "keytool doesn't accept that password for alias '$KEY_ALIAS' in $KEYSTORE_PATH."
    tries=$((tries + 1))
  done
  KEY_PW=""
  return 1
}

ask_keystore_path() {
  ask KEYSTORE_PATH "Path to the upload key (Enter = ~/teach-clock-upload.jks):" || KEYSTORE_PATH=""
  KEYSTORE_PATH=${KEYSTORE_PATH:-$HOME/teach-clock-upload.jks}
  KEYSTORE_PATH=${KEYSTORE_PATH/#\~/$HOME}
  write_env KEYSTORE_PATH "$KEYSTORE_PATH"
}

key_secrets_set() {
  has_secret ANDROID_KEYSTORE_BASE64 && has_secret ANDROID_KEYSTORE_PASSWORD &&
    has_secret ANDROID_KEY_ALIAS && has_secret ANDROID_KEY_PASSWORD
}

# tester_message prints the "Message for testers" quote from docs/android-release.md.
tester_message() {
  awk '/^### Message for testers/ { f = 1; next }
       f && /^##/ { exit }
       f && /^>/ { sub(/^> ?/, ""); print }' "$GUIDE"
}

# find_signed_artifact: the newest unexpired signed bundle from a successful CI run.
find_signed_artifact() {
  local id name
  CI_RUN="" CI_ARTIFACT=""
  for id in $(gh run list --workflow android.yml --status success --limit 20 \
    --json databaseId --jq '.[].databaseId' 2>/dev/null || true); do
    name=$(gh api "repos/{owner}/{repo}/actions/runs/$id/artifacts" \
      --jq '.artifacts[] | select(.expired | not) | .name' 2>/dev/null |
      grep -E '^teach-clock-[0-9]+$' | head -n1 || true)
    if [[ -n "$name" ]]; then CI_RUN=$id CI_ARTIFACT=$name; return 0; fi
  done
  return 1
}

# build_locally: npm run build:android, a signed bundleRelease, then the permission check.
build_locally() {
  if ! find_jdk; then warn "JDK 21 not found. Do the stage \"Your machine\" first."; return 1; fi
  if [[ -z "$KEYSTORE_PATH" ]]; then ask_keystore_path; fi
  if [[ ! -f "$KEYSTORE_PATH" ]]; then warn "No upload key at $KEYSTORE_PATH (stage \"Upload key\")."; return 1; fi
  ask_key_password || { warn "No password, no signed build."; return 1; }
  say "The commands (the password is passed through the environment, not shown):"
  show_cmd npm run build:android
  show_raw "(cd android && ./gradlew bundleRelease)"
  show_cmd npm run check:android
  if ! confirm "Build the signed bundle now (a few minutes)?"; then KEY_PW=""; return 1; fi
  if (( DRY_RUN )); then note "(dry run: not run)"; KEY_PW=""; return 0; fi
  local rc=0
  ( export JAVA_HOME="$JDK" ANDROID_HOME="$SDK_DIR" ANDROID_KEYSTORE_PATH="$KEYSTORE_PATH" \
      ANDROID_KEY_ALIAS="$KEY_ALIAS" ANDROID_KEYSTORE_PASSWORD="$KEY_PW" ANDROID_KEY_PASSWORD="$KEY_PW"
    npm run build:android && (cd android && ./gradlew bundleRelease) && npm run check:android ) || rc=$?
  KEY_PW=""
  if (( rc )); then warn "The build failed (exit $rc). Fix it, then run this stage again."; return 1; fi
  say "${GREEN}✓${RESET} Signed bundle: $ROOT/$AAB"
}

# ── Stages, in the order of the timeline in docs/android-release.md ──────

stage_start() {
  stage "Where you are"
  if (( GH_OK )); then
    say "GitHub: logged in${REPO:+, repo $REPO}."
  else
    warn "gh isn't installed or logged in (brew install gh; gh auth login)."
    note "Without it the wizard can't check or set secrets and variables; it lists them for you at the end."
  fi
  say ""
  say "Done so far:"
  local name label when
  for name in ANDROID_KEYSTORE_BASE64 ANDROID_KEYSTORE_PASSWORD ANDROID_KEY_ALIAS ANDROID_KEY_PASSWORD PLAY_SERVICE_ACCOUNT_JSON; do
    if has_secret "$name"; then step "secret $name ✓"; else step "secret $name: not set"; fi
  done
  for name in ANDROID_PACKAGE_ID VITE_SUPPORT_URL; do
    step "variable $name = $(var_value "$name" || true)"
  done
  while IFS= read -r label; do
    when=$(date_of "$label")
    step "$label: ${when:-—}"
  done <<'EOF'
Developer account verified
First build live on closed testing
Tester invite sent
12th tester opted in (day 1)
Day 14 (earliest "Apply for production")
Applied for production
Production access granted
First production release
Teacher Approved opt-in
EOF
  if (( DRY_RUN )); then
    say ""
    warn "Dry run: nothing is run or set; dates go to $CLOSED_TEST, progress to $ENV_FILE."
  fi
  say ""
  pause "Press Enter for the first stage"
}

stage_account() {
  stage "Play developer account (day 0, \$25)"
  if already DONE_ACCOUNT "Developer account verified"; then return 0; fi
  say "Do this first: Google checks your identity, which takes a few days."
  open_link "https://play.google.com/console/signup"
  step "Sign in with the Google account that will own the app (your own Gmail is fine)."
  step "Choose ${BOLD}Yourself${RESET} (personal account), not Organization."
  step "Developer name: shown on the store under the app (your name or \"Teach Clock\")."
  step "Pay ${BOLD}US\$25${RESET} with a bank card (not prepaid). Once, for good."
  step "Identity: legal name and address, an ID document; confirm email and phone with codes."
  step "Install the ${BOLD}Google Play Console${RESET} app on a real Android 10+ phone, sign in"
  say "  with the same account and verify the phone there."
  step "Wait for the \"identity verified\" email. The next four stages can be done meanwhile."
  say ""
  if confirm "Has your identity been verified (you got the email)?"; then
    record "Developer account verified" "Date it was verified?"
    mark_done DONE_ACCOUNT
  else
    note "Fine, carry on: the next four stages don't need the account."
  fi
  pause
}

stage_machine() {
  stage "Your machine: JDK 21 and Android SDK 36"
  local ok=1
  if find_jdk; then say "${GREEN}✓${RESET} JDK 21 at $JDK"; else
    ok=0
    warn "JDK 21 not found (keytool and Gradle need it)."
    offer "Install it with Homebrew now?" brew install openjdk@21 || true
  fi
  if [[ -d "$SDK_DIR/platforms/android-36" && -d "$SDK_DIR/build-tools/36.1.0" ]]; then
    say "${GREEN}✓${RESET} Android SDK 36 and build-tools 36.1.0 in $SDK_DIR"
  else
    ok=0
    warn "Android SDK 36 or build-tools 36.1.0 missing in $SDK_DIR."
    open_link "https://developer.android.com/studio"
    step "Install Android Studio, then Settings › Languages & Frameworks › Android SDK:"
    step "SDK Platforms: Android 16 (API 36); SDK Tools: Build-Tools 36, Platform-Tools, Emulator."
  fi
  say ""
  say "Put these in ~/.zshrc (Homebrew's JDK isn't found by java_home -v 21):"
  note "    export JAVA_HOME=\"\$(brew --prefix openjdk@21)\""
  note "    export ANDROID_HOME=\"\$HOME/Library/Android/sdk\""
  note "    export PATH=\"\$ANDROID_HOME/platform-tools:\$PATH\""
  if (( ok )); then say ""; say "Nothing to do here."; fi
  note "CI builds without any of this; you need it for the key and a local build."
  pause
}

stage_upload_key() {
  stage "Upload key (once; keep it safe)"
  say "Play App Signing keeps the real app key at Google. You keep only an upload key;"
  say "if you lose it, Play support can reset it."
  ask_keystore_path
  if [[ -f "$KEYSTORE_PATH" ]]; then
    say "${GREEN}✓${RESET} Found $KEYSTORE_PATH. Nothing to make."
    pause
    return 0
  fi
  if key_secrets_set; then
    warn "The four signing secrets are already in GitHub, but this file isn't here."
    note "Point the wizard at the file you made then. Make a new key only if the old one is lost,"
    note "and then ask Play support to reset the upload key (Play Console › Test and release › App signing)."
    if ! confirm "Make a new upload key anyway?"; then pause; return 0; fi
  fi
  local kt
  kt=$(keytool_bin) || { warn "No keytool: install JDK 21 (stage \"Your machine\") first."; pause; return 0; }
  say "keytool asks for a password (twice) and a few name questions. The names only go into"
  say "the certificate; your name and country UA are enough. For this kind of keystore the"
  say "key password is the keystore password: the secrets use the same one."
  if offer "Make the upload key now?" "$kt" -genkeypair -v -keystore "$KEYSTORE_PATH" -alias "$KEY_ALIAS" \
    -keyalg RSA -keysize 2048 -validity 10000; then
    warn "Back up $KEYSTORE_PATH and its password in your password manager now. Never commit it."
  fi
  pause
}

stage_key_secrets() {
  stage "The four signing secrets in GitHub"
  if key_secrets_set; then
    say "${GREEN}✓${RESET} ANDROID_KEYSTORE_BASE64, ANDROID_KEYSTORE_PASSWORD, ANDROID_KEY_ALIAS, ANDROID_KEY_PASSWORD are set."
    if ! confirm "Replace them (only after making a new upload key)?"; then return 0; fi
  fi
  if [[ ! -f "$KEYSTORE_PATH" ]]; then not_yet "the upload key: no file at ${KEYSTORE_PATH:-?}"; return 0; fi
  say "CI (.github/workflows/android.yml) signs every bundle with these. All four or none:"
  say "with some missing the build fails on purpose."
  ask_key_password || { warn "Skipped: no password."; pause; return 0; }
  show_raw "gh secret set ANDROID_KEYSTORE_BASE64 < <(base64 < $KEYSTORE_PATH)"
  show_raw "gh secret set ANDROID_KEYSTORE_PASSWORD   # the password, hidden"
  show_cmd gh secret set ANDROID_KEY_ALIAS --body "$KEY_ALIAS"
  show_raw "gh secret set ANDROID_KEY_PASSWORD        # the same password"
  if confirm "Set these four secrets${REPO:+ in $REPO}?"; then
    put_secret ANDROID_KEYSTORE_BASE64 "$(base64 < "$KEYSTORE_PATH" | tr -d '\n')"
    put_secret ANDROID_KEYSTORE_PASSWORD "$KEY_PW"
    put_secret ANDROID_KEY_ALIAS "$KEY_ALIAS"
    put_secret ANDROID_KEY_PASSWORD "$KEY_PW"
    refresh_gh
    note "From the next app change merged to main, CI makes a signed bundle."
  fi
  KEY_PW=""
  pause
}

stage_variables() {
  stage "Repository variables"
  local current
  current=$(var_value ANDROID_PACKAGE_ID || true)
  if [[ "$current" == "$PACKAGE_ID" ]]; then
    say "${GREEN}✓${RESET} ANDROID_PACKAGE_ID = $PACKAGE_ID (CI uploads to this app)."
  else
    say "ANDROID_PACKAGE_ID is '${current:-not set}'; CI needs $PACKAGE_ID to upload."
    if offer "Set it?" gh variable set ANDROID_PACKAGE_ID --body "$PACKAGE_ID"; then
      if (( ! DRY_RUN )); then refresh_gh; fi
    fi
  fi
  say ""
  current=$(var_value VITE_SUPPORT_URL || true)
  if [[ "$current" =~ ^https:// ]]; then
    say "${GREEN}✓${RESET} VITE_SUPPORT_URL = $current"
    if ! confirm "Change the support link?"; then pause; return 0; fi
  else
    say "VITE_SUPPORT_URL is '${current:-not set}', so the Web App shows no Support Button."
    say "It is the link to your monobank jar (it starts with https://send.monobank.ua/)."
    note "Web App only: the Android App and the Play listing never show it (Play payments policy)."
  fi
  if ! confirm "Set the support link now?"; then pause; return 0; fi
  if ask_https SUPPORT_URL "Your monobank jar link:"; then
    write_env SUPPORT_URL "$SUPPORT_URL"
    if offer "Set it?" gh variable set VITE_SUPPORT_URL --body "$SUPPORT_URL"; then
      if (( ! DRY_RUN )); then refresh_gh; fi
      say "The website picks it up at its next deploy."
      offer "Redeploy the website now?" gh workflow run deploy.yml --ref main || true
    fi
  fi
  pause
}

stage_create_app() {
  stage "Create the app in Play Console"
  if already DONE_CREATE_APP; then return 0; fi
  if [[ -z "$(date_of "Developer account verified")" ]] && ! is_done DONE_ACCOUNT; then
    not_yet "the identity check"
    return 0
  fi
  open_link "$PLAY_CONSOLE"
  step "Home › ${BOLD}Create app${RESET}"
  step "App name: ${BOLD}Вчимо годинник — гра для дітей${RESET}"
  step "Default language: ${BOLD}Українська – uk${RESET}"
  step "App or game: ${BOLD}Game${RESET}. Free or paid: ${BOLD}Free${RESET} (can never become paid)."
  step "Tick the declarations (Developer Program Policies, US export laws) › Create app."
  say ""
  if curl -fsSI --max-time 10 "$PRIVACY_URL" >/dev/null 2>&1; then
    say "${GREEN}✓${RESET} The Privacy Page answers: $PRIVACY_URL"
  else
    warn "Couldn't reach $PRIVACY_URL. Play needs it for the next stage; check the website deploy."
  fi
  if confirm "Is the app created?"; then mark_done DONE_CREATE_APP; fi
  pause
}

stage_app_content() {
  stage "App content: every answer"
  if already DONE_APP_CONTENT; then return 0; fi
  if ! is_done DONE_CREATE_APP; then not_yet "creating the app in Play Console"; return 0; fi
  open_link "$PLAY_CONSOLE"
  say "Dashboard › ${BOLD}Set up your app${RESET} (also Policy › App content). One form at a time:"
  say ""
  step "${BOLD}Privacy policy${RESET}: $PRIVACY_URL"; pause
  step "${BOLD}App access${RESET}: all functionality is available without special access"; pause
  step "${BOLD}Ads${RESET}: No, the app contains no ads"; pause
  step "${BOLD}Content rating${RESET}: questionnaire, category Game; no violence, no user interaction,"
  say "  no sharing, no purchases. Expect 3+ / PEGI 3."; pause
  step "${BOLD}Target audience and content${RESET}: ages 6–8 and 9–12 only (Families policy)"; pause
  step "${BOLD}News app${RESET}: No"; pause
  step "${BOLD}Data safety${RESET}: does the app collect or share user data? No"
  say "  (the name and Preferences stay on the device and are never sent)"; pause
  step "${BOLD}Government app${RESET}: No. ${BOLD}Financial features${RESET}: none. ${BOLD}Health${RESET}: none"; pause
  step "${BOLD}App category${RESET} (Store settings): Game › Educational, tags as offered;"
  say "  contact email: yours; website: $WEBSITE_URL"; pause
  if confirm "Are all the App content forms done?"; then mark_done DONE_APP_CONTENT; fi
}

stage_listing() {
  stage "Store listing: texts and graphics"
  if already DONE_LISTING; then return 0; fi
  if ! is_done DONE_CREATE_APP; then not_yet "creating the app in Play Console"; return 0; fi
  open_link "$PLAY_CONSOLE"
  say "Grow users › Store presence › ${BOLD}Main store listing${RESET} (Ukrainian is the default):"
  step "App name, short and full description: the text blocks in docs/store/listing.uk.md"
  step "App icon: docs/store/icon-512.png. Feature graphic: docs/store/feature-graphic.png"
  step "Phone screenshots: docs/store/screenshots/uk/1-welcome.png … 8-summary.png (all 8)"
  step "Add a translation › English (en-US): docs/store/listing.en.md and screenshots/en/"
  step "Website: $WEBSITE_URL. No donation or jar text anywhere."
  if (( DRY_RUN )); then open_link "$ROOT/docs/store"; else
    offer "Open docs/store in Finder?" open "$ROOT/docs/store" || true
  fi
  pause "Press Enter when the listing is saved"
  if confirm "Is the listing done in both languages?"; then mark_done DONE_LISTING; fi
}

stage_first_bundle() {
  stage "A signed bundle for the first upload"
  if already DONE_FIRST_UPLOAD "First build live on closed testing"; then return 0; fi
  say "Google takes API uploads only after one build is uploaded by hand, so CI can't do"
  say "this one. Get a signed .aab from CI, or build it here."
  say ""
  if (( GH_OK )) && find_signed_artifact; then
    say "${GREEN}✓${RESET} CI has a signed bundle: artifact ${BOLD}$CI_ARTIFACT${RESET} (run $CI_RUN; kept 14 days)."
    if offer "Download it to ~/Downloads/$CI_ARTIFACT?" \
      gh run download "$CI_RUN" --name "$CI_ARTIFACT" --dir "$HOME/Downloads/$CI_ARTIFACT"; then
      say "The file: ~/Downloads/$CI_ARTIFACT/app-release.aab"
      pause
      return 0
    fi
  else
    note "No signed CI bundle yet. One appears after the next merge to main that changes the app,"
    note "once the four signing secrets are set (artifact teach-clock-<run number>)."
  fi
  if confirm "Build a signed bundle here instead?"; then build_locally || true; fi
  pause
}

stage_first_upload() {
  stage "First upload: closed testing"
  if already DONE_FIRST_UPLOAD "First build live on closed testing"; then return 0; fi
  if ! is_done DONE_CREATE_APP; then not_yet "creating the app in Play Console"; return 0; fi
  open_link "$PLAY_CONSOLE"
  step "Test and release › Testing › ${BOLD}Closed testing${RESET} › the default track ${BOLD}Alpha${RESET}"
  warn "Use Alpha, not a new track: CI uploads every merge to the track id 'alpha'."
  step "Create release › upload the .aab › accept ${BOLD}Play App Signing${RESET} when asked."
  step "Release notes: uk \"Перша версія\", en \"First version\"."
  step "Countries: Ukraine (and wherever your testers live)."
  step "Testers: a Google Group (next stage). Then send the release for review."
  say ""
  if confirm "Is the release sent for review?"; then mark_done DONE_FIRST_UPLOAD; fi
  if confirm "Has Google approved it (the track shows it available to testers)?"; then
    record "First build live on closed testing" "Date it went live?"
  fi
  pause
}

stage_testers() {
  stage "Testers: Google Group, opt-in link, message"
  if already DONE_TESTERS "Tester invite sent"; then return 0; fi
  if ! is_done DONE_FIRST_UPLOAD; then not_yet "the first upload to closed testing"; return 0; fi
  open_link "https://groups.google.com/my-groups"
  step "Create group, for example ${BOLD}teach-clock-testers${RESET}; anyone can ask to join (or you add people)."
  step "Play Console › Closed testing › Alpha › ${BOLD}Testers${RESET} › Google Groups: add the group's email."
  step "On the same tab copy the ${BOLD}opt-in link${RESET} (https://play.google.com/apps/testing/$PACKAGE_ID)."
  say ""
  ask_https GROUP_URL "Google Group link:" && write_env GROUP_URL "$GROUP_URL"
  ask_https OPTIN_URL "Opt-in link:" && write_env OPTIN_URL "$OPTIN_URL"
  local msg
  msg=$(tester_message)
  msg=${msg//"<посилання на Google Group>"/"${GROUP_URL:-<посилання на Google Group>}"}
  msg=${msg//"<Google Group link>"/"${GROUP_URL:-<Google Group link>}"}
  msg=${msg//"<посилання для тестувальників>"/"${OPTIN_URL:-<посилання для тестувальників>}"}
  msg=${msg//"<opt-in link>"/"${OPTIN_URL:-<opt-in link>}"}
  say ""
  say "Send this to about 15 people (12 must stay opted in for 14 days in a row):"
  printf '%s\n' "$msg" | sed 's/^/    /'
  say ""
  if command -v pbcopy >/dev/null 2>&1 && (( ! DRY_RUN )); then
    if confirm "Copy it to the clipboard?"; then printf '%s\n' "$msg" | pbcopy; say "${GREEN}✓${RESET} Copied."; fi
  fi
  note "Track them in docs/store/closed-test.md as T1, T2… only: the repo is public."
  if confirm "Have you sent the invite?"; then
    record "Tester invite sent" "Date sent?"
    mark_done DONE_TESTERS
  fi
  pause
}

stage_service_account() {
  stage "Service account: CI uploads every merge"
  if has_secret PLAY_SERVICE_ACCOUNT_JSON; then
    say "${GREEN}✓${RESET} PLAY_SERVICE_ACCOUNT_JSON is set."
    if ! confirm "Replace it with a new key?"; then return 0; fi
  fi
  if ! is_done DONE_FIRST_UPLOAD; then not_yet "the first upload to closed testing"; return 0; fi
  open_link "https://console.cloud.google.com/projectcreate"
  step "Create a project, for example ${BOLD}teach-clock-play${RESET} (no billing needed)."
  pause
  open_link "https://console.cloud.google.com/apis/library/androidpublisher.googleapis.com"
  step "Enable ${BOLD}Google Play Android Developer API${RESET} in that project."
  pause
  open_link "https://console.cloud.google.com/iam-admin/serviceaccounts"
  step "Create service account, for example ${BOLD}play-uploader${RESET}; no roles."
  step "Open it › Keys › Add key › Create new key › ${BOLD}JSON${RESET}: a file downloads."
  pause
  open_link "$PLAY_CONSOLE"
  step "Users and permissions › ${BOLD}Invite new users${RESET} › the service account's email"
  say "  (play-uploader@…iam.gserviceaccount.com) › App permissions › Teach Clock:"
  step "${BOLD}Release to testing tracks${RESET} and ${BOLD}Release to production${RESET} (plus View app information)."
  step "Invite user."
  say ""
  local tries=0
  while (( tries < 3 )); do
    ask JSON_PATH "Path to the downloaded JSON key:" || break
    JSON_PATH=${JSON_PATH/#\~/$HOME}
    if [[ -f "$JSON_PATH" ]] && grep -q '"type": *"service_account"' "$JSON_PATH"; then break; fi
    warn "That isn't a service account JSON key."
    JSON_PATH="" tries=$((tries + 1))
  done
  if [[ -z "$JSON_PATH" ]]; then warn "Skipped: no key file."; pause; return 0; fi
  say "Service account: $(sed -n 's/.*"client_email": *"\([^"]*\)".*/\1/p' "$JSON_PATH")"
  show_raw "gh secret set PLAY_SERVICE_ACCOUNT_JSON < $JSON_PATH"
  if confirm "Set the secret${REPO:+ in $REPO}?"; then
    put_secret PLAY_SERVICE_ACCOUNT_JSON "$(cat "$JSON_PATH")"
    refresh_gh
    offer "Delete the downloaded key file now (it is in GitHub; Google can make a new one)?" rm -f "$JSON_PATH" || true
  fi
  say ""
  say "From now on each merge to main that changes the app uploads a new bundle to"
  say "closed testing (track alpha, notes \"Покращення та виправлення\" / \"Improvements and fixes\")."
  pause
}

stage_closed_test() {
  stage "Closed test: 12 testers, 14 days"
  if already DONE_CLOSED_TEST 'Day 14 (earliest "Apply for production")'; then return 0; fi
  if [[ -z "$(date_of "Tester invite sent")" ]] && ! is_done DONE_TESTERS; then
    not_yet "inviting the testers"
    return 0
  fi
  open_link "$PLAY_CONSOLE"
  say "Dashboard › ${BOLD}Apply for production${RESET} shows how many testers are opted in and"
  say "how many days the rule has been met. Google's count decides; check it every few days."
  note "Log it in docs/store/closed-test.md (daily log, feedback): you need it for the application."
  say ""
  if confirm "Has the Dashboard reached 12 opted-in testers?"; then
    local day1=""
    if ask_date day1 "First day with 12 opted in?"; then
      set_date "12th tester opted in (day 1)" "$day1"
      local day14; day14=$(add_days "$day1" 14)
      set_date 'Day 14 (earliest "Apply for production")' "$day14"
      say ""
      warn "Reminder: on $day14, if the Dashboard says 14 days met, run the wizard and Apply for production."
      note "If fewer than 12 stay opted in, the 14 days start again: run this stage again then."
    fi
  fi
  pause
}

stage_apply() {
  stage "Apply for production"
  if already DONE_APPLY "Production access granted"; then return 0; fi
  local day14 applied
  day14=$(date_of 'Day 14 (earliest "Apply for production")')
  if [[ -z "$day14" ]]; then not_yet "12 testers are opted in (the closed test stage)"; return 0; fi
  if [[ "$(date +%F)" < "$day14" ]]; then not_yet "day 14 of the closed test: $day14"; return 0; fi
  applied=$(date_of "Applied for production")
  if [[ -z "$applied" ]]; then
    open_link "$PLAY_CONSOLE"
    step "Dashboard › ${BOLD}Apply for production${RESET} (only when it says 14 days met)."
    step "Answer briefly and truthfully: how you recruited testers, what they said, what you"
    say "  changed, who the app is for, why it's ready. Drafts: docs/store/closed-test.md."
    if confirm "Have you applied?"; then record "Applied for production" "Date applied?"; applied=yes; fi
  else
    say "Applied on $applied. Google usually answers within 7 days."
  fi
  if [[ -n "$applied" ]] && confirm "Has Google granted production access?"; then
    record "Production access granted" "Date granted?"
    mark_done DONE_APPLY
  fi
  pause
}

stage_production() {
  stage "First production release"
  if already DONE_PRODUCTION "First production release"; then return 0; fi
  if [[ -z "$(date_of "Production access granted")" ]]; then not_yet "Google grants production access"; return 0; fi
  say "GitHub › Actions › ${BOLD}Android app bundle${RESET} › ${BOLD}Run workflow${RESET} (branch main) with"
  say "release notes in Ukrainian and English, at most 500 characters each. It builds a new"
  say "bundle from main and uploads it straight to production; Google reviews it (hours to days)."
  if ! has_secret PLAY_SERVICE_ACCOUNT_JSON; then
    warn "PLAY_SERVICE_ACCOUNT_JSON isn't set, so the run would fail. Do the service account stage first."
  elif confirm "Start it from here?"; then
    ask NOTES_UK "Release notes, Ukrainian:" || NOTES_UK=""
    ask NOTES_EN "Release notes, English:" || NOTES_EN=""
    if [[ -n "$NOTES_UK" && -n "$NOTES_EN" ]]; then
      offer "Release to production now?" gh workflow run android.yml --ref main \
        -f notes_uk="$NOTES_UK" -f notes_en="$NOTES_EN" || true
    else
      warn "Both notes are needed."
    fi
  else
    open_link "https://github.com/${REPO:-denysslobodianyk1996/teach-clock}/actions/workflows/android.yml"
  fi
  say ""
  if confirm "Is the release live on Google Play?"; then
    record "First production release" "Date it went live?"
    mark_done DONE_PRODUCTION
  fi
  pause
}

stage_teacher_approved() {
  stage "Teacher Approved"
  if already DONE_TEACHER "Teacher Approved opt-in"; then return 0; fi
  if [[ -z "$(date_of "First production release")" ]]; then not_yet "the first production release"; return 0; fi
  open_link "$PLAY_CONSOLE"
  step "Grow › ${BOLD}Teacher Approved${RESET} (or the Families section) › opt in."
  if confirm "Have you opted in?"; then
    record "Teacher Approved opt-in" "Date?"
    mark_done DONE_TEACHER
  fi
  pause
}

STAGES=(stage_start stage_account stage_machine stage_upload_key stage_key_secrets
  stage_variables stage_create_app stage_app_content stage_listing stage_first_bundle
  stage_first_upload stage_testers stage_service_account stage_closed_test stage_apply
  stage_production stage_teacher_approved)

run_wizard() {

parse_args "$@"
cd "$ROOT"
TOTAL_STAGES=${#STAGES[@]}
ENV_FILE="$ROOT/.env.release"
if (( DRY_RUN )); then
  local tmp; tmp=$(mktemp -d)
  if [[ -f "$ENV_FILE" ]]; then cp "$ENV_FILE" "$tmp/.env.release"; fi
  cp "$CLOSED_TEST" "$tmp/closed-test.md"
  ENV_FILE="$tmp/.env.release" CLOSED_TEST="$tmp/closed-test.md"
fi
refresh_gh

banner "Teach Clock on Google Play"

local fn
for fn in "${STAGES[@]}"; do "$fn"; done

finish
if (( DRY_RUN )); then
  note "Dry run: what would have changed in docs/store/closed-test.md:"
  diff "$ROOT/docs/store/closed-test.md" "$CLOSED_TEST" | sed 's/^/    /' || true
elif ! git diff --quiet -- docs/store/closed-test.md; then
  note "docs/store/closed-test.md has new dates: commit them."
fi
}

run_wizard "$@"; exit
